'use client'

import * as React from 'react'

import { Accordion } from '@chakra-ui/react/accordion'

import { ChevronRightIcon } from '../../icons/chevron-right-icon'

export interface ItemTriggerProps extends Accordion.ItemTriggerProps {
  indicatorIcon?: React.ReactNode
  indicatorPlacement?: 'start' | 'end'
}

export const ItemTrigger = React.forwardRef<
  HTMLButtonElement,
  ItemTriggerProps
>(function AccordionItemTrigger(props, ref) {
  const {
    children,
    indicatorPlacement = 'end',
    indicatorIcon = <ChevronRightIcon />,
    ...rest
  } = props

  const indicator = (
    <Accordion.ItemIndicator>{indicatorIcon}</Accordion.ItemIndicator>
  )

  return (
    <Accordion.ItemTrigger {...rest} ref={ref}>
      {indicatorPlacement === 'start' && indicator}
      {children}
      {indicatorPlacement === 'end' && indicator}
    </Accordion.ItemTrigger>
  )
})

export interface ItemContentProps extends Accordion.ItemContentProps {}

export const ItemContent = React.forwardRef<HTMLDivElement, ItemContentProps>(
  function AccordionItemContent(props, ref) {
    return (
      <Accordion.ItemContent>
        <Accordion.ItemBody {...props} ref={ref} />
      </Accordion.ItemContent>
    )
  },
)

export const Root = Accordion.Root
export const Item = Accordion.Item

export type RootProps = Accordion.RootProps
export type ItemProps = Accordion.ItemProps

'use client'

import { forwardRef } from 'react'

import { ActionBar } from '@chakra-ui/react/action-bar'
import { Portal } from '@chakra-ui/react/portal'

import { CloseButton as CloseButtonBase } from '../close-button/index.ts'

interface ActionBarContentProps extends ActionBar.ContentProps {
  portalled?: boolean
  portalRef?: React.RefObject<HTMLElement>
}

const ActionBarContent = forwardRef<HTMLDivElement, ActionBarContentProps>(
  function ActionBarContent(props, ref) {
    const { children, portalled = true, portalRef, ...rest } = props

    return (
      <Portal disabled={!portalled} container={portalRef}>
        <ActionBar.Positioner>
          <ActionBar.Content ref={ref} {...rest} asChild={false}>
            {children}
          </ActionBar.Content>
        </ActionBar.Positioner>
      </Portal>
    )
  },
)

const ActionBarCloseButton = forwardRef<
  HTMLButtonElement,
  ActionBar.CloseTriggerProps
>(function ActionBarCloseTrigger(props, ref) {
  return (
    <ActionBar.CloseTrigger {...props} asChild ref={ref}>
      <CloseButtonBase size="sm" />
    </ActionBar.CloseTrigger>
  )
})

export const Root = ActionBar.Root
export const SelectionTrigger = ActionBar.SelectionTrigger
export const Separator = ActionBar.Separator
export const Content = ActionBarContent
export const CloseButton = ActionBarCloseButton

export type RootProps = ActionBar.RootProps
export type SelectionTriggerProps = ActionBar.SelectionTriggerProps
export type SeparatorProps = ActionBar.SeparatorProps
export type ContentProps = ActionBarContentProps
export type CloseTriggerProps = ActionBar.CloseTriggerProps

'use client'

import { forwardRef } from 'react'

import { Alert as AlertPrimitive } from '@chakra-ui/react/alert'

import { CloseButton } from '../close-button/index.ts'

export interface AlertProps extends Omit<AlertPrimitive.RootProps, 'title'> {
  startElement?: React.ReactNode
  endElement?: React.ReactNode
  title?: React.ReactNode
  icon?: React.ReactElement
  closable?: boolean
  onClose?: () => void
}

export const Alert = forwardRef<HTMLDivElement, AlertProps>(
  function Alert(props, ref) {
    const {
      title,
      children,
      icon,
      closable,
      onClose,
      startElement,
      endElement,
      ...rest
    } = props
    return (
      <AlertPrimitive.Root ref={ref} {...rest}>
        {startElement || (
          <AlertPrimitive.Indicator>{icon}</AlertPrimitive.Indicator>
        )}
        {children ? (
          <AlertPrimitive.Content>
            <AlertPrimitive.Title>{title}</AlertPrimitive.Title>
            <AlertPrimitive.Description>{children}</AlertPrimitive.Description>
          </AlertPrimitive.Content>
        ) : (
          <AlertPrimitive.Title flex="1">{title}</AlertPrimitive.Title>
        )}
        {endElement}
        {closable && (
          <CloseButton
            size="sm"
            pos="relative"
            top="-2"
            insetEnd="-2"
            alignSelf="flex-start"
            onClick={onClose}
          />
        )}
      </AlertPrimitive.Root>
    )
  },
)

'use client'

import { forwardRef } from 'react'

import {
  type HTMLChakraProps,
  createSlotRecipeContext,
} from '@chakra-ui/react/styled-system'
import {
  type AppShellVariantProps,
  appShellSlotRecipe,
} from '@saas-ui/chakra-preset/slot-recipes/app-shell'

////////////////////////////////////////////////////////////////////////////////////

const {
  withProvider,
  withContext,
  useStyles: useAppShellStyles,
} = createSlotRecipeContext({
  recipe: appShellSlotRecipe,
})

export { useAppShellStyles }

export interface AppShellBaseProps {
  /**
   * The top header navigation
   */
  header?: React.ReactNode
  /**
   * Main sidebar, positioned on the left
   */
  sidebar?: React.ReactElement
  /**
   * Secondary sidebar, positioned on the right
   */
  aside?: React.ReactNode
  /**
   * The footer
   */
  footer?: React.ReactNode
}

export interface AppShellRootProps
  extends HTMLChakraProps<'div'>, AppShellVariantProps {}

/**
 * The App Shell defines the main structure of your app.
 *
 * @see Docs https://saas-ui.dev/docs/components/layout/app-shell
 */
export const AppShellRoot = withProvider<HTMLDivElement, AppShellRootProps>(
  'div',
  'root',
  { forwardAsChild: true },
)

export interface AppShellContentProps extends HTMLChakraProps<'div'> {}

export const AppShellContent = withContext<
  HTMLDivElement,
  AppShellContentProps
>('div', 'content', { forwardAsChild: true })

export interface AppShellMainProps extends HTMLChakraProps<'div'> {}

export const AppShellMain = withContext<HTMLDivElement, AppShellMainProps>(
  'div',
  'main',
  { forwardAsChild: true },
)

export interface AppShellProps
  extends AppShellBaseProps, HTMLChakraProps<'div'>, AppShellVariantProps {}

export const AppShell = forwardRef<HTMLDivElement, AppShellProps>(
  (props, ref) => {
    const { header, sidebar, aside, footer, children, ...rootProps } = props

    return (
      <AppShellRoot ref={ref} {...rootProps}>
        {header}
        <AppShellContent>
          {sidebar}
          <AppShellMain>{children}</AppShellMain>
          {aside}
        </AppShellContent>
        {footer}
      </AppShellRoot>
    )
  },
)

AppShell.displayName = 'AppShell'

