        ref={ref}
        me="-2"
        aspectRatio="square"
        size="sm"
        variant="ghost"
        colorPalette="gray"
        height="calc(100% - {spacing.2})"
        aria-label="Toggle password visibility"
        {...props}
      />
    )
  },
)

