const dataAttr = (condition: boolean | undefined) =>
  condition ? '' : undefined

interface PersonaRootProps
  extends
    HTMLChakraProps<'div'>,
    SlotRecipeProps<'suiPersona'>,
    PersonaVariantProps {
  /**
   * Indicates that a person is out of office. Changes the presence badge style.
