      panelRadius = 1,
      indicatorRadius = 1,
      overlayEffect = 'blur(10px)',
      ...rest
    } = props

    const variables: ThemeVariables = {
      '--scale-factor': scaleFactor,
      '--overlay-effect': overlayEffect,
      '--radius-control': controlRadius,
      '--radius-panel': panelRadius,
      '--radius-indicator': indicatorRadius,
    }

    return (
      <chakra.div
        color="fg"
        bg={hasBackground ? 'bg' : undefined}
        colorPalette="gray"
        {...rest}
        className={cx('chakra-theme', appearance, className)}
        style={{ ...style, colorScheme: appearance, ...variables }}
        ref={ref}
      />
    )
  },
)

'use client'

import React, { useCallback, useMemo, useState } from 'react'

import { Portal } from '@chakra-ui/react/portal'
import { Stack } from '@chakra-ui/react/stack'
import {
  Toaster as ChakraToaster,
  type CreateToasterProps,
  CreateToasterReturn,
  Toast,
  createToaster,
} from '@chakra-ui/react/toast'

import { CloseButton } from '../close-button/index.ts'
import { Spinner } from '../spinner/index.ts'

export type { CreateToasterProps, CreateToasterReturn }

const defaultOptions: CreateToasterProps = {
  placement: 'bottom-end',
  pauseOnPageIdle: true,
}

export let toast = createToaster(defaultOptions) as CreateToasterReturn

export interface ToasterProps extends Partial<CreateToasterProps> {
  closable?: boolean
}

export const Toaster = (props?: ToasterProps) => {
  const { closable: defaultClosable = true, ...options } = props || {}

  const toaster = useMemo(() => {
    toast = createToaster({
      ...defaultOptions,
      ...options,
    })

    return toast
  }, [options])

  return (
    <Portal>
      <ChakraToaster toaster={toaster} insetInline={{ mdDown: '4' }}>
        {(toast) => {
          const closable =
            toast.meta?.closable === false
              ? false
              : defaultClosable && toast.type !== 'loading'

          return (
            <ToastRoot>
              {toast.type === 'loading' ? (
                <Spinner size="sm" color="colorPalette.solid" mt="0.5" />
              ) : (
                <Toast.Indicator />
              )}
              <Stack gap="1" flex="1" maxWidth="100%">
                {toast.title && <Toast.Title>{toast.title}</Toast.Title>}
                {toast.description && (
                  <Toast.Description>{toast.description}</Toast.Description>
                )}

                {toast.action && (
                  <Toast.ActionTrigger>
                    {toast.action.label}
                  </Toast.ActionTrigger>
                )}
              </Stack>

              {closable !== false && (
                <Toast.CloseTrigger asChild>
                  <CloseButton size="xs" />
                </Toast.CloseTrigger>
              )}
            </ToastRoot>
          )
        }}
      </ChakraToaster>
    </Portal>
  )
}

/**
 * Since the height of the toast is dynamic, we need to set the height
 * in the CSS variable `--toast-height` so css transitions can be applied.
 */
function ToastRoot(props: { children: React.ReactNode }) {
  const [rect, setRect] = useState<DOMRect>()

  const rectCallbackRef = useCallback((el: HTMLDivElement) => {
    setRect(el?.getBoundingClientRect())
  }, [])

  return (
    <Toast.Root
      ref={rectCallbackRef}
      width={{ md: 'sm' }}
      css={{
        '--toast-height': `${rect?.height}px`,
      }}
    >
      {props.children}
    </Toast.Root>
  )
}

'use client'

import * as React from 'react'

import { Popover } from '../popover/index.ts'
import { Portal } from '../portal/index.ts'

export interface ToggleTipProps extends Popover.RootProps {
  /**
   * Whether to show the arrow.
   * @default true
   */
  showArrow?: boolean
  /**
   * Whether to portall the content.
   * @default true
   */
  portalled?: boolean
  /**
   * The ref to the portal.
   */
  portalRef?: React.RefObject<HTMLElement>
  /**
   * The content to display in the tooltip.
   */
  content?: React.ReactNode
  /**
   * The trigger element.
   */
  children: React.ReactNode
}

export const ToggleTip = React.forwardRef<HTMLDivElement, ToggleTipProps>(
  function ToggleTip(props, ref) {
    const {
      showArrow,
      children,
      portalled = true,
      content,
      portalRef,
      ...rest
    } = props

    return (
      <Popover.Root {...rest} positioning={{ ...rest.positioning, gutter: 4 }}>
        <Popover.Trigger asChild>{children}</Popover.Trigger>

        <Portal disabled={!portalled} container={portalRef}>
          <Popover.Content
            width="auto"
            px="2"
            py="1"
            textStyle="xs"
            rounded="sm"
            ref={ref}
          >
            {showArrow && <Popover.Arrow />}
            {content}
          </Popover.Content>
        </Portal>
      </Popover.Root>
    )
  },
)

'use client'

import * as React from 'react'

import { chakra } from '@chakra-ui/react'

export type LinkComponent = React.ElementType

export interface LinkProviderProps {
  children: React.ReactNode
  component?: LinkComponent
}

const LinkContext = React.createContext<LinkComponent>(chakra.a)

export function LinkProvider(props: LinkProviderProps) {
  const { children, component = chakra.a } = props

  return (
    <LinkContext.Provider value={component}>{children}</LinkContext.Provider>
  )
}

export function useLink(): LinkComponent {
  return React.useContext(LinkContext)
}

